void LCD_Delay(unsigned int delay)
{
	LCD_Timing_Delay = delay;
	while(--LCD_Timing_Delay != 0);
}


void LCD_Data_Pin_Change(unsigned char mode)
{
	GPIO_InitTypeDef GPIO_InitStruct;

	if(mode == LCD_Input)
	{
		GPIO_InitStruct.Pin = C_LDATA0_Pin|C_LDATA1_Pin|C_LDATA2_Pin|C_LDATA3_Pin 
			|C_LDATA4_Pin|C_LDATA5_Pin|C_LDATA6_Pin|C_LDATA7_Pin;
		GPIO_InitStruct.Mode = GPIO_MODE_INPUT;
		GPIO_InitStruct.Pull = GPIO_NOPULL;
		HAL_GPIO_Init(GPIOD, &GPIO_InitStruct);
	}
	else if(mode == LCD_Output)
	{
		GPIO_InitStruct.Pin = C_LDATA0_Pin|C_LDATA1_Pin|C_LDATA2_Pin|C_LDATA3_Pin 
			|C_LDATA4_Pin|C_LDATA5_Pin|C_LDATA6_Pin|C_LDATA7_Pin;
		GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP;
		GPIO_InitStruct.Pull = GPIO_NOPULL;
		GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_HIGH;
		HAL_GPIO_Init(GPIOD, &GPIO_InitStruct);
	}
}

//GPIO port bit set/reset register : BSRR
//GPIO port bit reset srgister : BRR
//GPIO port  output data register : ODR
void LCD_Data_Write(unsigned char address, unsigned short data)
{
	unsigned char data_high = data>>8;
	unsigned char data_low = data&0xFF;

	CHIP_SEL_ON;	//LCD_CHIP_SEL_On

	IND_LCD_REG_SEL;	//IND_LCD_REG_SEL

	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	LCD_Read_Off;	//LCD_Read_Off
	LCD_Write_Off;	//LCD_Write_Off

	LCD_Data_Pin_Change(LCD_Output);

	//GPIOD->ODR = GPIOD->ODR & 0xFF00;
	GPIOD->BSRR = 0xFF0000;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	
	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + address;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = address;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	CON_LCD_REG_SEL;	//CON_LCD_REG_SEL
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + data_high;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = data_high;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + data_low;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = data_low;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	GPIOD->BSRR = 0x1000;	//LCD_CHIP_SEL_Off

}//함수콜하는 시간이 있어서 콜하는 시간을 줄이기 위해 GPIO에 값을 바로 쓰기


void LCD_RGB_Write_Data(unsigned short data)
{
	unsigned char data_high = data>>8;
	unsigned char data_low = data&0xFF;

	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + data_high;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = data_high;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + data_low;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = data_low;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

}


//addrsss가 0x0000이면 첫번째칸 0x0001이면 두번째칸...... 0x00AF이면 176번째칸
//address가 0x0000이면 첫번재줄 0x0100이면 두번째줄...... 0xDB00이면 220번째줄 
//0x0000 ~~ 0xDBAF
void LCD_RAM_ADD_Set(unsigned short address)
{
	LCD_Data_Write(0x20, ((address&0xFF00)>>8));
	LCD_Data_Write(0x21, (address&0x00FF));
}

void LCD_RGB_Write_Setting(void)
{
	CHIP_SEL_ON;	//LCD_CHIP_SEL_On

	IND_LCD_REG_SEL;	//IND_LCD_REG_SEL
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	
	LCD_Read_Off;	//LCD_Read_Off
	LCD_Write_Off;	//LCD_Write_Off

	LCD_Data_Pin_Change(LCD_Output);

	//GPIOD->ODR = GPIOD->ODR & 0xFF00;
	GPIOD->BSRR = 0xFF0000;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	//GPIOD->ODR = (GPIOD->ODR & 0xFF00) + 0x22;
	GPIOD->BSRR = 0xFF0000;
	GPIOD->BSRR = 0x22;
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_On;	//LCD_Write_On
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY
	LCD_Write_Off;	//LCD_Write_Off
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

	CON_LCD_REG_SEL;	//CON_LCD_REG_SEL
	LCD_Delay(1); //++,--, 220621 ysm, LCD_DELAY

}

void Display_Logo(void)
{   
	LCD_Draw_Color(0, 0, LCD_WIDTH, LCD_HEIGHT, COLOR_BLACK);
	
	PCXtoBMP_16bit(25, 5, 169, 120, (unsigned int)&Forklift_Icon);
    PCXtoBMP_16bit(10, 125, 200, 31, (unsigned int)&intro_logo);
}


