unsigned short DisplayStringAtWidth(unsigned short *s, uint16_t x,uint16_t y,  uint16_t width, GUI_FONT* pNewFont[], uint32_t Color)
{
	unsigned char Intens;
	unsigned char* fontIntens;
	unsigned short font_Width, font_Height;
	unsigned short i, j, Len = 0, c = 0, x_pos = 0, old_font_Width = 0;
	unsigned short Index;
	unsigned char bFind = 0;
	GUI_FONT* pFont1[NUMBEROFFONT];
	unsigned char max = 2;
	GUI_FONT_PROP* pProp;	

	c = (*s++);

	for(i=0;i<NUMBEROFFONT;i++)
		pFont1[i] = (GUI_FONT*)pNewFont[i];

	if(pFont1[0] == pFont1[1])
		max = 1;
	else if(pFont1[1] == 0x0)
		max = 1;
	else
		max = NUMBEROFFONT;	

	font_Height = pFont1[0]->YSize;		// Font Height ??

	x_pos = x;

	while((c != 0) && (Len <= 0x7fff))
	{
		for(Index = 0; Index<max;Index++)
		{
			if((Index > 0) && (bFind == 1))
				Index = 0;
			for (pProp = (GUI_FONT_PROP*)pFont1[Index]->pProp ; ; pProp = (GUI_FONT_PROP*)pProp->pNext) 
			{
				if(pProp == 0)
				{
					bFind = 0;
					break;
				}

				if ((c >= pProp->First) && (c <= pProp->Last))
				{
					bFind = 1;
					break;
				}
			}

			if(bFind == 1)
			{
				font_Width = (pProp->paCharInfo+(c-pProp->First))->XSize;		// Font Widht ??
				x_pos += old_font_Width;
				old_font_Width = font_Width;

				fontIntens = (unsigned char*)(pProp->paCharInfo+(c-pProp->First))->pData;
				
				if((x_pos+font_Width) >= (x+width))
					return x_pos;

				for(i = 0 ; i < font_Height ; i++)
				{
					for(j = 0 ; j < font_Width ; j+= 2)
					{
						//if((x_pos+j) >= (x+width))
						//	return x_pos;
						Intens = ((*fontIntens) & 0xF0) >> 4;

						if(Intens != 0) 
						{
							LCD_Draw_Pixel_Buffer((x_pos + j), y+i, Color);
						}

						Intens = ((*fontIntens) & 0x0f);

						if(Intens != 0) 
						{
							LCD_Draw_Pixel_Buffer((x_pos + j+1), y+i, Color);
						}

						fontIntens++;
					}
				}

				Len++;	

				c = (*s++);		// ?? ????????....
			}

		}
		if(bFind == 0)
			return x_pos;
	}

	return x_pos;
}

unsigned short DisplayMultiLineCenterStringAt(unsigned short *s, uint16_t x,uint16_t y, unsigned short width, unsigned short height, GUI_FONT* pNewFont[], uint32_t Color)
{
	unsigned char LineCount;
	unsigned short y_offset;
	unsigned short fontHeight;

	LineCount = GetStringMultiLine(s, pNewFont, width);
	y_offset = 0;
	fontHeight = pNewFont[0]->YSize;

	if(height == 0)
	{
		y_offset = 0;
	}
	else
	{
		y_offset = (height - (LineCount * fontHeight))/2;
		if((height - (LineCount * fontHeight)) % 2 == 1)
			y_offset -= 1;
	}

	for(int i=0;i<LineCount;i++)
	{
		unsigned short offset;
		unsigned int strLength;

		unsigned short covbuf[100];
		memset((&covbuf[0]), 0x0, sizeof( covbuf));

		if(i == 0)
			memcpy(&covbuf[0], &s[0], arrMultiLen[i]*sizeof(unsigned short));
		else
			memcpy(&covbuf[0], &s[arrMultiLen[i-1]], (arrMultiLen[i]-arrMultiLen[i-1])*sizeof(unsigned short));

		strLength = GetStringLen(covbuf, pNewFont);

		if(strLength < width)
			offset = (width - strLength)/2;
		else 
			offset = 0; 

		DisplayStringAt(covbuf, x+offset, y+y_offset, pNewFont, Color);

		y_offset += fontHeight;
	}

	return y_offset;
}


